#[component]
fn App() -> impl IntoView {
    let (user, set_user) = signal(String::new());
    let can_submit = move || !user.get().trim().is_empty();
    view! {
        <input on:input=move |ev| set_user.set(event_target_value(&ev)) />
        <button disabled=move || !can_submit() on:click=move |_| submit(user.get())>
            "Sign in"
        </button>
    }
}
